function financeMoney($value): string { return 'RM ' . number_format((float)$value, 2); }
function financeDocLabel(string $type): string { return ucwords(str_replace('_', ' ', $type)); }
function financeAgingTotal(array $rows, string $bucket): float {
    return array_sum(array_map(fn($r) => ($r['aging_bucket'] ?? '') === $bucket ? (float)$r['balance_due'] : 0, $rows));
}
$monthNames = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
