        <article class="fc-card"><div class="fc-card-head"><div><h3>FY <?= $year ?> Budgets</h3><p>Allocation versus actual supplier bills.</p></div><?php if($canSettings && $costCenters): ?><button class="fc-btn primary" onclick="App.openModal('budgetModal')">Set Budget</button><?php endif; ?></div><div class="fc-table-wrap"><table class="fc-table"><thead><tr><th>Scope</th><th>Allocated</th><th>Actual</th><th>Usage</th></tr></thead><tbody><?php if(!$budgets): ?><tr><td colspan="4" class="fc-empty">No budget allocation for this fiscal year.</td></tr><?php endif; ?><?php foreach($budgets as $budget): $pct=(float)$budget['allocated_amount']>0?min(999,((float)$budget['actual_spend']/(float)$budget['allocated_amount'])*100):0; ?><tr><td><strong><?= htmlspecialchars($budget['code']) ?></strong><div class="fc-muted"><?= htmlspecialchars($budget['project_ref']?:'All projects') ?></div></td><td class="fc-money"><?= financeMoney($budget['allocated_amount']) ?></td><td class="fc-money"><?= financeMoney($budget['actual_spend']) ?></td><td><div class="fc-progress"><span style="width:<?= min(100,$pct) ?>%;background:<?= $pct>100?'#DC2626':'#0F766E' ?>"></span></div><div class="fc-muted"><?= number_format($pct,1) ?>%</div></td></tr><?php endforeach; ?></tbody></table></div></article>
