    <section class="fc-panel" id="fcProfit"><article class="fc-card"><div class="fc-card-head"><div><h3>Project Profitability — FY <?= $year ?></h3><p>Revenue from sales invoices minus supplier bills and approved employee expenses.</p></div></div><div class="fc-table-wrap"><table class="fc-table"><thead><tr><th>Project Reference</th><th>Revenue</th><th>Direct Cost</th><th>Gross Profit</th><th>Margin</th></tr></thead><tbody><?php if(!$profitability): ?><tr><td colspan="5" class="fc-empty">Add a Project Reference to invoices, bills and expense claims to calculate profitability.</td></tr><?php endif; ?><?php foreach($profitability as $project): $margin=(float)$project['revenue']>0?((float)$project['profit']/(float)$project['revenue'])*100:0; ?><tr><td><strong><?= htmlspecialchars($project['project_ref']) ?></strong></td><td class="fc-money" style="color:#15803D"><?= financeMoney($project['revenue']) ?></td><td class="fc-money" style="color:#B91C1C"><?= financeMoney($project['cost']) ?></td><td class="fc-money"><?= financeMoney($project['profit']) ?></td><td><span class="fc-badge <?= $margin>=0?'good':'danger' ?>"><?= number_format($margin,1) ?>%</span></td></tr><?php endforeach; ?></tbody></table></div></article></section>

    <section class="fc-panel" id="fcRecurring"><div class="fc-grid">
        <article class="fc-card"><div class="fc-card-head"><div><h3>Recurring Bills</h3><p>Automatically generate monthly, quarterly or annual bills.</p></div><?php if($canSettings): ?><button class="fc-btn primary" onclick="App.openModal('recurringModal')">Add Rule</button><?php endif; ?></div><div class="fc-table-wrap"><table class="fc-table"><thead><tr><th>Vendor / Bill</th><th>Frequency</th><th>Next Run</th><th>Amount</th></tr></thead><tbody><?php if(!$recurringRules): ?><tr><td colspan="4" class="fc-empty">No recurring bill rules.</td></tr><?php endif; ?><?php foreach($recurringRules as $rule): ?><tr><td><strong><?= htmlspecialchars($rule['party_name']) ?></strong><div class="fc-muted"><?= htmlspecialchars($rule['title']) ?></div></td><td><?= htmlspecialchars(ucfirst($rule['frequency'])) ?></td><td><?= htmlspecialchars($rule['next_run_date']) ?></td><td class="fc-money"><?= financeMoney($rule['amount']*(1+$rule['tax_rate']/100)) ?></td></tr><?php endforeach; ?></tbody></table></div></article>
        <article class="fc-card"><div class="fc-card-head"><div><h3>Finance Settings</h3><p>Company-wide defaults used by new workflow documents.</p></div></div><form onsubmit="submitFinanceForm(event,'save_finance_settings')"><div class="fc-form-grid"><input type="hidden" name="csrf_token" value="<?= Helper::csrfToken() ?>"><div class="fc-field"><label>Default Currency</label><input class="fc-control" name="default_currency" maxlength="10" value="<?= htmlspecialchars($settings['default_currency']??'MYR') ?>"></div><div class="fc-field"><label>SST Rate (%)</label><input class="fc-control" type="number" min="0" max="100" step="0.001" name="sst_rate" value="<?= htmlspecialchars($settings['sst_rate']??'8.00') ?>"></div><div class="fc-field"><label>Invoice Terms (Days)</label><input class="fc-control" type="number" min="0" max="365" name="invoice_terms_days" value="<?= htmlspecialchars($settings['invoice_terms_days']??'30') ?>"></div><div class="fc-field"><label>Fiscal Year Start Month</label><input class="fc-control" type="number" min="1" max="12" name="fiscal_year_start_month" value="<?= htmlspecialchars($settings['fiscal_year_start_month']??'1') ?>"></div></div><?php if($canSettings): ?><div class="fc-form-footer"><button class="fc-btn primary" type="submit">Save Settings</button></div><?php endif; ?></form></article>
    </div></section>
</main>

