<script>
function openFinancePanel(button){document.querySelectorAll('.fc-tab').forEach(x=>x.classList.toggle('active',x===button));document.querySelectorAll('.fc-panel').forEach(x=>x.classList.toggle('active',x.id===button.dataset.panel));}
async function postSimple(action,values,button){const fd=new FormData();fd.append('csrf_token',window.CSRF_TOKEN||'');Object.entries(values).forEach(([k,v])=>fd.append(k,v));const result=await App.post('index.php?action='+action,fd,button);if(result?.status==='success')setTimeout(()=>location.reload(),600);}
function convertFinanceRecord(id,button){const target=document.getElementById('target-'+id)?.value;if(target)postSimple('convert_finance_record',{source_id:id,target_type:target},button);}
function matchBankTransaction(id,button){const paymentId=document.getElementById('bank-match-'+id)?.value;if(!paymentId){App.showToast('error','Select a matching payment first.');return;}postSimple('match_bank_transaction',{transaction_id:id,payment_id:paymentId},button);}
function openPaymentModal(record){document.getElementById('payRecordId').value=record.id;document.getElementById('payAmount').value=Number(record.balance).toFixed(2);document.getElementById('payAmount').max=record.balance;document.getElementById('payDocumentLabel').textContent=record.reference+' — '+record.party+' — Balance RM '+Number(record.balance).toFixed(2);App.openModal('paymentModal');}
async function submitFinanceForm(event,action){event.preventDefault();const button=event.submitter;const result=await App.post('index.php?action='+action,new FormData(event.target),button);if(result?.status==='success'){document.querySelectorAll('.modal-overlay.active').forEach(m=>App.closeModal(m.id));setTimeout(()=>location.reload(),600);}}
</script>

